+export type PlatformId = "win" | "android" | "iphone" | "pi" | "ubuntu";
+export type SchemeId =
+  | "violet"
+  | "ocean"
+  | "cyan"
+  | "green"
+  | "emerald"
+  | "sunset"
+  | "orange"
+  | "crimson"
+  | "atlantis"
+  | "vision";
+
